function renderGame(){
 if(!game)return;
 var g=game,timed=g.mode!=='relaxed';
 var prompt={bop:'Bop a mouse when it peeks out!',bloom:'Snip the flowers. Watch them grow again!',scurry:'Drop cheese to guide the mouse home!',bouquet:'Snip the matching flowers for the bouquet!',countries:'Match each country to its place on the map!',gauchos:'Round up the wandering herd and bring them home!',peaks:'Guide the climber up the route to the summit!',biomes:'Find each wild place on the map of South America!',animals:'Send each animal home to the right wild place!',market:'Count out the right coins to buy the treat!',timeline:'Put these moments in order, oldest first!'}[g.type];
 var bodies={scurry:mazeView,countries:puzzleView,gauchos:herdView,peaks:climbView,biomes:biomeView,animals:sortView,market:marketView,timeline:timelineView};
 var body=(bodies[g.type]||classicField)(g);
 var tips={scurry:'Click, tap, or use arrow keys / W A S D to drop cheese.',countries:'Tap a country from the list, then tap its spot on the map.',gauchos:'Tap a cow to send it home to the corral.',peaks:'Tap the next dot up the route.',biomes:'Tap a wild place, then tap its circle on the map.',animals:'Tap the habitat where this animal lives.',market:'Tap coins until they add up to the price.',timeline:'Tap the card that happened earliest.'};
 var tip=tips[g.type]||'Click or tap to play. Keyboard: Q W E / A S D / Z X C, or 1–9.';
 shell('<main><div class="game-header"><div class="game-heading"><button class="icon-button" data-action="home" aria-label="Back to playroom">'+icon('home')+'</button><h1>'+esc(current().name)+'’s '+gameNames[g.type]+'</h1></div><div class="scoreboard"><div class="score"><small>'+gameScores[g.type]+'</small><span id="score">'+g.score+'</span></div><div class="score"><small>'+(timed?'SECONDS':'YOUR PACE')+'</small><span id="time">'+(timed?Math.ceil(60-g.elapsed):'∞')+'</span></div><button class="icon-button" data-action="pause" aria-label="Pause game">'+icon('pause')+'</button></div></div>'+difficultyRow(g)+'<div class="progress-track"><div id="progress" class="progress-bar"></div></div><div class="playfield '+g.type+'-field"><div class="field-top"><span>'+prompt+'</span><strong>'+(timed?'Let’s explore':'No hurry. Just play.')+'</strong></div>'+body+'<div id="pause-layer"></div></div><div class="field-footer"><span class="game-tip">'+tip+'</span><button class="pill" data-action="finish">'+icon('check')+'All done</button></div></main>');
 if(g.paused)showPause();
}
function tick(now){
 if(!game)return;
 var g=game,elapsed=Math.max(0,(now-g.last)/1000),dt=Math.min(elapsed,.1);
 g.last=now;
 if(!g.paused&&!g.ended){
  g.elapsed+=elapsed;
  if(g.mode!=='relaxed'&&g.elapsed>=60){finishGame();return;}
  if(g.type==='bop'){
   var active=0;
   g.slots.forEach(function(s,i){if(s.active){active++;if(g.mode!=='relaxed'&&g.elapsed>s.until){s.active=false;var el=$('#target-'+i);if(el)el.classList.remove('ready');}}});
   g.spawn-=dt;var max=g.mode==='speedy'?4:g.mode==='gentle'?3:2;
   if(g.spawn<=0&&active<max){
    var available=[];g.slots.forEach(function(s,i){if(!s.active&&g.elapsed>s.cut)available.push(i);});
    if(available.length){var index=available[Math.floor(Math.random()*available.length)],slot=g.slots[index];slot.active=true;slot.until=g.elapsed+(g.mode==='speedy'?1.6:3.3);g.spawned=(g.spawned||0)+1;var el=$('#target-'+index);if(el){el.className='target ready';el.setAttribute('aria-label','Bop mouse '+(index+1));}}
    g.spawn=g.mode==='speedy'?.4:.75;
   }
  } else if(g.type==='bloom'||g.type==='bouquet'){
   g.slots.forEach(function(s,i){
    if(g.elapsed<s.cut)return;
    s.growth=Math.min(1,s.growth+dt/(g.mode==='speedy'?2.5:4.5));
    var el=$('#target-'+i);
    if(el){el.querySelector('svg').innerHTML=flowerArt(s.species,s.hue,s.growth);el.setAttribute('aria-label',(s.growth>=.95?'Blooming flower ':'Growing flower ')+(i+1));if(g.type==='bouquet')el.classList.toggle('wanted',s.growth>=.95&&matchTargetIndex(g,s)>=0);}
   });
   if(g.type==='bouquet')tickBouquetTimeout(g,dt);
  } else if(g.type==='gauchos'&&g.herd&&g.herd.speed&&!g.herd.celebrating){
   g.herd.cows.forEach(function(c){
    c.retarget-=dt;
    if(c.retarget<=0){c.vx=(Math.random()*2-1)*g.herd.speed;c.vy=(Math.random()*2-1)*g.herd.speed;c.retarget=1.5+Math.random()*2;}
    c.x+=c.vx*dt*10;c.y+=c.vy*dt*10;
    if(c.x<6){c.x=6;c.vx=Math.abs(c.vx);}if(c.x>78){c.x=78;c.vx=-Math.abs(c.vx);}
    if(c.y<8){c.y=8;c.vy=Math.abs(c.vy);}if(c.y>86){c.y=86;c.vy=-Math.abs(c.vy);}
    var el=document.getElementById('cow-'+c.id);
    if(el){el.style.left=c.x+'%';el.style.top=c.y+'%';}
   });
  }
  if(g.mode!=='relaxed'){var t=$('#time');if(t)t.textContent=Math.max(0,Math.ceil(60-g.elapsed));var pr=$('#progress');if(pr)pr.style.width=(Math.max(0,1-g.elapsed/60)*100)+'%';}
 }
 g.frame=requestAnimationFrame(tick);
}
function hit(index){
 if(!game||game.paused||game.ended)return;
 var g=game,s=g.slots[index],el=$('#target-'+index);
 if(!el)return;
 if(g.type==='bop'){
  if(!s.active)return;
  s.active=false;s.cut=g.elapsed+.4;el.classList.remove('ready');el.classList.add('hit');el.setAttribute('aria-label','Empty mouse path '+(index+1));
  tone('bop');
 } else if(g.type==='bloom'){
  if(s.growth<.28||g.elapsed<s.cut)return;
  var fresh=newFlowerSlot();s.growth=0;s.cut=g.elapsed+.35;s.species=fresh.species;s.hue=fresh.hue;
  el.querySelector('svg').innerHTML=flowerArt(s.species,s.hue,0);
  tone('snip');
 } else if(g.type==='bouquet'){
  if(s.growth<.28||g.elapsed<s.cut)return;
  var ti=matchTargetIndex(g,s);
  if(ti<0){el.classList.add('nope');tone('nope');setTimeout(function(){el.classList.remove('nope');},420);return;}
  g.vase[ti]=true;
  var fresh2=newFlowerSlot();s.growth=0;s.cut=g.elapsed+.35;s.species=fresh2.species;s.hue=fresh2.hue;
  tone('snip');
  if(g.vase.every(function(v){return v;})){
   g.score++;
   tone('finish');toast('Bouquet complete! A new one is waiting.');
   newBouquetRound(g);
  }
  renderGame();
  return;
 } else return;
 var pop=document.createElement('span');pop.className='pop-score';pop.textContent=g.type==='bop'?'★':'✂';el.appendChild(pop);
 setTimeout(function(){if(pop.parentNode)pop.parentNode.removeChild(pop);},650);
 g.score++;var scoreEl=$('#score');if(scoreEl)scoreEl.textContent=g.score;
}
function pauseGame(){if(!game||game.paused)return;game.paused=true;showPause();audioSync();}
function showPause(){var layer=$('#pause-layer');if(layer)layer.innerHTML='<div class="pause-cover"><div><h2>A little breather.</h2><p>Your garden will wait for you.</p><button class="big-button" data-action="resume">'+icon('play')+'Keep playing</button></div></div>';}
function resumeGame(){if(!game)return;game.paused=false;game.last=performance.now();$('#pause-layer').innerHTML='';audioSync();}
function stopGame(){if(game&&game.frame)cancelAnimationFrame(game.frame);game=null;}
function completeAssignment(g){
 if(!g.assignmentId)return 0;
 var p=current();
 var a=(p.assignments||[]).filter(function(x){return x.id===g.assignmentId;})[0];
 if(!a||(a.completed&&!a.recurring))return 0;
 var earned=10+g.score;
 a.completedAt=Date.now();a.score=g.score;a.timesPlayed=(a.timesPlayed||0)+1;
 if(!a.recurring)a.completed=true;
 p.points=(p.points||0)+earned;
 save();
 return earned;
}
function finishGame(){
 if(!game||game.ended)return;
 game.ended=true;
 cancelAnimationFrame(game.frame);
 var g=game,p=current(),best=false;
 if(g.mode!=='relaxed'&&g.score>p.best[g.type]){p.best[g.type]=g.score;best=true;save();}
 var earned=completeAssignment(g);
 tone('finish');
 var resultText=g.type==='bop'?(g.score+' of '+(g.spawned||g.score)+' mice caught'):(g.score+' '+gameLabels[g.type]);
 var bestText=g.mode!=='relaxed'?' · best '+p.best[g.type]:'';
 toast((best?'New personal best! ':'')+resultText+bestText+'. Lovely playing, '+p.name+'!'+(earned?' +'+earned+' points!':''));
 stopGame();draft=null;closeModal();screen='home';render();
}
function pressTarget(e){var t=e.target.closest('[data-action="hit"]');if(t){e.preventDefault();unlockAudio();hit(Number(t.getAttribute('data-index')));}}
if(window.PointerEvent){root.addEventListener('pointerdown',pressTarget);}else{root.addEventListener('mousedown',pressTarget);root.addEventListener('touchstart',pressTarget,{passive:false});}
document.addEventListener('click',function(e){var b=e.target.closest('[data-action]');if(!b)return;unlockAudio();var a=b.getAttribute('data-action'),v=b.getAttribute('data-value');
 if(a==='hit'){if(e.detail===0)hit(Number(b.getAttribute('data-index')));return;}
 if(a==='home'){stopGame();draft=null;closeModal();screen='home';render();}
 else if(a==='start')startGame(b.getAttribute('data-game'),b.getAttribute('data-assignment'));
 else if(a==='home-tab'){homeTab=v;render();}
 else if(a==='settings'){pauseGame();draft=null;closeModal();screen='settings';render();}
 else if(a==='back-game'){screen='game';render();}
 else if(a==='workshop'){draft=copy(current());screen='workshop';render();}
 else if(a==='mute'){state.settings.muted=!state.settings.muted;save();audioSync();b.innerHTML=icon(state.settings.muted?'mute':'sound');b.setAttribute('aria-label',state.settings.muted?'Turn sound on':'Mute all sound');b.setAttribute('aria-pressed',state.settings.muted);if(screen==='settings')settings();}
 else if(a==='profiles')profiles();
 else if(a==='parent-gate')parentGate();
 else if(a==='pin-digit'){if(pinEntry.length<4)pinEntry+=v;updatePinDialog();}
 else if(a==='pin-back'){pinEntry=pinEntry.slice(0,-1);updatePinDialog();}
 else if(a==='manage-profile'){managing=b.getAttribute('data-id');render();}
 else if(a==='toggle-game'){var mp=managedProfile(),gid=b.getAttribute('data-id'),gi=mp.enabledGames.indexOf(gid);if(gi>=0){if(mp.enabledGames.length>1)mp.enabledGames.splice(gi,1);}else mp.enabledGames.push(gid);save();render();}
 else if(a==='toggle-diff'){var mp2=managedProfile(),did=b.getAttribute('data-id'),di=mp2.enabledDifficulties.indexOf(did);if(di>=0){if(mp2.enabledDifficulties.length>1)mp2.enabledDifficulties.splice(di,1);}else mp2.enabledDifficulties.push(did);save();render();}
 else if(a==='assign-game'){var mp3=managedProfile(),sel=$('#assign-game'),recurEl=$('#assign-recurring');mp3.assignments=mp3.assignments||[];mp3.assignments.push({id:id(),gameId:sel.value,assignedAt:Date.now(),recurring:!recurEl||recurEl.getAttribute('aria-checked')==='true',completed:false,completedAt:null,score:0,timesPlayed:0});save();render();toast('Assigned to '+esc(mp3.name)+'!');}
 else if(a==='toggle-assign-recurring'){var checked=b.getAttribute('aria-checked')==='true';b.setAttribute('aria-checked',!checked);}
 else if(a==='remove-assignment'){var mp4=managedProfile(),aid=b.getAttribute('data-id');mp4.assignments=(mp4.assignments||[]).filter(function(x){return x.id!==aid;});save();render();}
 else if(a==='save-pin'){var v1=$('#new-pin-1').value,v2=$('#new-pin-2').value;if(!/^\d{4}$/.test(v1)){$('#pin-save-error').textContent='PIN must be 4 digits.';return;}if(v1!==v2){$('#pin-save-error').textContent='PINs don’t match.';return;}state.parentPin=v1;save();toast('Parent PIN updated.');render();}
 else if(a==='close-modal')closeModal();
 else if(a==='add-profile')addProfile();
 else if(a==='select-profile'){stopGame();state.active=b.getAttribute('data-id');save();draft=null;closeModal();screen='home';render();}
 else if(a==='shuffle'){var options=palettes.filter(function(p){return p.primary!==draft.colors.primary;});draft.colors=copy(options[Math.floor(Math.random()*options.length)]);draft.mascot=mascots[(mascots.indexOf(draft.mascot)+1+Math.floor(Math.random()*(mascots.length-1)))%mascots.length];draft.style=styles[(styles.indexOf(draft.style)+1+Math.floor(Math.random()*(styles.length-1)))%styles.length];draft.pattern=patterns[(patterns.indexOf(draft.pattern)+1+Math.floor(Math.random()*(patterns.length-1)))%patterns.length];workshop();tone('hello');}
 else if(a==='apply-palette'){draft.colors=copy(palettes[Number(b.getAttribute('data-index'))]);workshop();}
 else if(a==='mascot'){draft.mascot=v;workshop();}
 else if(a==='lettering'){draft.style=v;workshop();}
 else if(a==='pattern'){draft.pattern=v;workshop();}
 else if(a==='save-style'){if(!draft.name.trim()){toast('Your playroom needs a name.');$('#edit-name').focus();return;}draft.name=draft.name.trim();var p=current();p.name=draft.name;p.colors=copy(draft.colors);p.style=draft.style;p.mascot=draft.mascot;p.pattern=draft.pattern;save();draft=null;screen='home';render();toast('Your playroom, your style. Saved!');}
 else if(a==='toggle'){state.settings[v]=!state.settings[v];save();render();}
 else if(a==='test-sound'){tone('hello');}
 else if(a==='pause')pauseGame();
 else if(a==='resume')resumeGame();
 else if(a==='finish')finishGame();
 else if(a==='maze-cell'){mazeClick(Number(b.getAttribute('data-x')),Number(b.getAttribute('data-y')));}
 else if(a==='sa-select'){
  var cid=b.getAttribute('data-country');
  if(game.puzzle.selected===cid){game.puzzle.selected=null;game.puzzle.fact='';}
  else{game.puzzle.selected=cid;var facts=saFacts[cid]||[];game.puzzle.fact=facts.length?facts[Math.floor(Math.random()*facts.length)]:'';}
  renderGame();
 }
 else if(a==='sa-cell'){saClickCell(b.getAttribute('data-country'));}
 else if(a==='herd-cow'){herdClickCow(Number(b.getAttribute('data-id')));}
 else if(a==='climb-step'){climbStep(Number(b.getAttribute('data-idx')));}
 else if(a==='next-peak'){newClimbRound(game);renderGame();}
 else if(a==='maze-new'){newMazeRound(game);renderGame();}
 else if(a==='maze-retry'){game.trail=[{x:0,y:0}];game.celebrating=false;renderGame();}
 else if(a==='speak-fact'){if(game&&game.fact)speakText(game.fact);}
 else if(a==='biome-select'){
  var bid=b.getAttribute('data-biome');
  game.biome.selected=game.biome.selected===bid?null:bid;
  renderGame();
 }
 else if(a==='biome-spot'){biomeClickSpot(b.getAttribute('data-biome'));}
 else if(a==='speak-biome'){var sb=game&&game.biome&&game.biome.selected?biomeById(game.biome.selected):null;if(sb)speakText(sb.name+'. '+sb.fact);}
 else if(a==='sort-bin'){sortPick(b.getAttribute('data-habitat'));}
 else if(a==='market-coin'){marketCoin(Number(b.getAttribute('data-value')));}
 else if(a==='market-reset'){game.market.paid=0;renderGame();}
 else if(a==='timeline-pick'){timelinePick(Number(b.getAttribute('data-idx')));}
 else if(a==='set-difficulty'){var p=current();p.difficulty[game.type]=v;save();startGame(game.type,game.assignmentId);}
});
document.addEventListener('keydown',function(e){
 if(modalRoot.firstChild){if(e.key==='Tab'){var els=modalRoot.querySelectorAll('button:not([disabled]),input,select');var first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}if(e.key==='Escape'&&!(game&&game.ended)){closeModal();}return;}
 if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;
 if(game&&screen==='game'){
  if(e.key==='Escape'||e.key===' '){e.preventDefault();game.paused?resumeGame():pauseGame();return;}
  var k=e.key.toLowerCase();
  if(game.type==='scurry'){if(!e.repeat&&mazeKeyDirs.hasOwnProperty(k)){e.preventDefault();unlockAudio();mazeDirectionMove(k);}return;}
  if(['countries','gauchos','peaks','biomes','animals','market','timeline'].indexOf(game.type)>=0)return;
  var idx='qweasdzxc'.indexOf(k);
  if(/^[1-9]$/.test(k))idx=Number(k)-1;
  if(idx>=0&&!e.repeat){e.preventDefault();unlockAudio();hit(idx);}
 }
});
